// Status page: renders metrics generated by scripts/dora_metrics.py and checks
// live service health from the browser. Builds the DOM with textContent only.

const LIVE_TIMEOUT_MS = 70_000;
const RECHECK_MS = 30_000;

function el(tag, props = {}, children = []) {
  const node = document.createElement(tag);
  if (props.className) node.className = props.className;
  if (props.text !== undefined) node.textContent = String(props.text);
  if (props.href) {
    node.href = props.href;
    node.target = "_blank";
    node.rel = "noopener noreferrer";
  }
  if (props.title) node.title = props.title;
  children.forEach((child) => node.appendChild(child));
  return node;
}

function chip(text, kind) {
  return el("span", { className: `chip ${kind}`, text });
}

function duration(seconds) {
  if (seconds === null || seconds === undefined) return "n/a";
  if (seconds < 90) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  if (minutes < 90) return `${minutes}m ${String(seconds % 60).padStart(2, "0")}s`;
  const hours = Math.floor(minutes / 60);
  return hours < 48 ? `${hours}h ${minutes % 60}m` : `${Math.round(hours / 24)}d`;
}

function when(iso) {
  if (!iso) return "";
  return iso.replace("T", " ").slice(0, 16);
}

const RESULT_LABELS = {
  success: "success",
  rolled_back: "rolled back",
  rollback_failed: "rollback failed",
  failed: "failed",
  not_approved: "not approved",
  refused: "refused, unsigned",
};

const RATING_TEXT = {
  elite: "Elite",
  high: "High",
  medium: "Medium",
  low: "Low",
  "no data": "No data yet",
};

function tile(label, value, detail, rating) {
  const kids = [el("span", { className: "label", text: label }), el("span", { className: "value", text: value })];
  if (rating) kids.push(el("span", {}, [chip(RATING_TEXT[rating] ?? rating, rating === "no data" ? "nodata" : rating)]));
  if (detail) kids.push(el("span", { className: "detail", text: detail }));
  return el("article", { className: "tile" }, kids);
}

function renderDora(m) {
  const d = m.dora;
  const freq = d.deploymentFrequency;
  const lead = d.leadTime;
  const cfr = d.changeFailureRate;
  const ttr = d.timeToRestore;
  document.getElementById("dora-window").textContent =
    m.observedDays < m.windowDays ? `over ${m.observedDays} day(s) since the first deploy` : `over the last ${m.windowDays} days`;

  document.getElementById("dora").replaceChildren(
    tile("Deployment frequency", `${freq.perWeek} / week`,
      `${freq.count} successful production deploys`, freq.rating),
    tile("Lead time for changes", duration(lead.medianSeconds),
      `Median commit to production. ${duration(lead.medianPipelineSeconds)} excluding approval wait.`, lead.rating),
    tile("Change failure rate", cfr.rate === null ? "n/a" : `${Math.round(cfr.rate * 100)}%`,
      `${cfr.failures} of ${cfr.attempts} production deploys failed or rolled back. Drills excluded.`, cfr.rating),
    tile("Time to restore", duration(ttr.medianSeconds),
      `Median from failure detected to service verified, ${ttr.samples} incident(s).`, ttr.rating),
  );

  const ci = m.pipeline.ci;
  document.getElementById("extra").replaceChildren(
    tile("Median build", duration(m.pipeline.medianBuildSeconds), `${m.pipeline.builds} builds, 3 services, 2 architectures`),
    tile("CI pass rate", ci.passRate === null ? "n/a" : `${Math.round(ci.passRate * 100)}%`, `${ci.runs} CI runs`),
    tile("Stopped before production", String(d.stoppedBeforeProduction), "Real releases caught in staging"),
    tile("Rollback drills", String(d.drills), "Deliberate failure demos run"),
  );
}

function renderDeployments(m) {
  const body = document.getElementById("deployments");
  if (!m.deployments.length) {
    body.replaceChildren(el("tr", {}, [el("td", { className: "muted", text: "No deployments yet." })]));
    return;
  }
  body.replaceChildren(
    ...m.deployments.map((d) => {
      const result = el("td", {}, [chip(RESULT_LABELS[d.result] ?? d.result, d.result)]);
      if (d.demo) result.appendChild(document.createTextNode(" "));
      if (d.demo) result.appendChild(chip("drill", "demo"));
      const runCell = el("td", {}, [el("a", { href: d.runUrl, text: "view" })]);
      if (d.incidentUrl) {
        runCell.appendChild(document.createTextNode(" · "));
        runCell.appendChild(el("a", { href: d.incidentUrl, text: "incident" }));
      }
      return el("tr", {}, [
        el("td", { text: when(d.startedAt) }),
        el("td", { text: d.environment }),
        el("td", { className: "mono", text: d.version || (d.sha ? d.sha.slice(0, 7) : "n/a") }),
        el("td", { text: d.workflow }),
        result,
        el("td", { text: duration(d.durationSeconds) }),
        runCell,
      ]);
    }),
  );
}

function renderLists(m) {
  const releases = document.getElementById("releases");
  releases.replaceChildren(
    ...(m.releases.length
      ? m.releases.map((r) => el("li", {}, [el("a", { href: r.url, text: r.tag }), el("span", { className: "muted", text: when(r.publishedAt) })]))
      : [el("li", { className: "muted", text: "No releases yet." })]),
  );
  const incidents = document.getElementById("incidents");
  incidents.replaceChildren(
    ...(m.incidents.length
      ? m.incidents.map((i) =>
          el("li", {}, [
            el("a", { href: i.url, text: `#${i.number} ${i.title}` }),
            el("span", {}, [chip(i.restoreSeconds !== null ? `restored in ${duration(i.restoreSeconds)}` : i.state, i.state === "open" ? "warn" : "good")]),
          ]),
        )
      : [el("li", { className: "muted", text: "No incidents." })]),
  );
}

async function getJson(url) {
  const res = await fetch(url, { signal: AbortSignal.timeout(LIVE_TIMEOUT_MS) });
  if (!res.ok) throw new Error(`${url} returned ${res.status}`);
  return res.json();
}

function serviceRow(name, state, info) {
  const version = info ? `${info.version} at ${String(info.commit ?? "").slice(0, 7)}` : "";
  return el("div", { className: "service" }, [
    el("strong", { text: name }),
    el("span", { className: "mono", text: version }),
    chip(state, state),
  ]);
}

async function checkEnvironment(env, card) {
  const list = card.querySelector(".services");
  const [web, status] = await Promise.allSettled([getJson(`${env.web}/version`), getJson(`${env.api}/status`)]);
  const rows = [serviceRow("web", web.status === "fulfilled" ? "up" : "waking", web.value)];
  if (status.status === "fulfilled") {
    for (const svc of status.value.services) rows.push(serviceRow(svc.name, svc.state, svc.version));
  } else {
    rows.push(serviceRow("api", "waking"), serviceRow("worker", "waking"));
  }
  list.replaceChildren(...rows);
  const waking = rows.some((row) => row.querySelector(".chip.waking, .chip.down"));
  const commits = new Set(
    [web.value?.commit, ...(status.value?.services ?? []).map((s) => s.version?.commit)].filter(Boolean),
  );
  const badge = card.querySelector(".badge");
  badge.replaceChildren(
    waking ? chip("waking up", "waking") : commits.size === 1 ? chip("one build everywhere", "good") : chip("mixed builds", "warn"),
  );
  return waking;
}

async function checkAll(config) {
  const container = document.getElementById("environments");
  if (!container.children.length) {
    container.replaceChildren(
      ...config.environments.map((env) =>
        el("article", { className: `env ${env.name}` }, [
          el("div", { className: "env-head" }, [el("h3", { text: env.name }), el("span", { className: "badge" }, [chip("checking", "neutral")])]),
          el("a", { href: env.web, text: env.web.replace("https://", "") }),
          el("div", { className: "services" }, [el("span", { className: "muted", text: "Contacting services..." })]),
        ]),
      ),
    );
  }
  const cards = [...container.children];
  const results = await Promise.all(config.environments.map((env, i) => checkEnvironment(env, cards[i])));
  const anyWaking = results.some(Boolean);
  document.getElementById("wake-note").hidden = !anyWaking;
  document.getElementById("live-checked").textContent = `checked live at ${new Date().toLocaleTimeString()}`;
  if (anyWaking) setTimeout(() => checkAll(config), RECHECK_MS);
}

async function init() {
  let metrics;
  try {
    metrics = await getJson("data/metrics.json");
  } catch {
    document.getElementById("footer").textContent = "Pipeline data is not available yet.";
    return;
  }
  const repoUrl = `https://github.com/${metrics.repository}`;
  document.getElementById("repo-link").href = repoUrl;
  document.getElementById("runs-link").href = `${repoUrl}/actions`;
  renderDora(metrics);
  renderDeployments(metrics);
  renderLists(metrics);
  document.getElementById("footer").textContent =
    `Metrics generated ${when(metrics.generatedAt)} UTC from GitHub Actions runs, deploy records, releases and incident issues. ` +
    "Regenerated after every deploy and every 6 hours.";
  checkAll(metrics.config);
}

init();
